<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Add <?= ucfirst($type) ?></h1><p>Record an auditable <?= $type ?> transaction under the correct account head.</p></div><a class="btn btn--secondary" href="<?= url('/admin/accounts') ?>">Manage Account Heads</a></header><section class="module-card"><header class="module-card__header"><h2>Transaction Details</h2></header><div class="module-card__body"><form method="post" action="<?= url('/admin/accounts/'.$type) ?>"><?= csrf_field() ?><div class="module-form-grid module-form-grid--three"><div class="module-field"><label>Account Head <span class="required">*</span></label><select class="module-select" name="account_head" required><option value="">Select account head</option><?php foreach($heads as$head):if($head['status']!=='active'||!in_array($head['type'],[$type,'both'],true))continue;?><option value="<?= $head['id'] ?>" <?= (string)old('account_head')===(string)$head['id']?'selected':'' ?>><?= e($head['name']) ?></option><?php endforeach?></select><?php if(error('account_head')):?><p class="field-error"><?= e(error('account_head')) ?></p><?php endif?></div><div class="module-field"><label>Date <span class="required">*</span></label><input class="module-input" name="expensedate" type="date" value="<?= e(old('date',date('Y-m-d'))) ?>" required></div><div class="module-field"><label>Description <span class="required">*</span></label><input class="module-input" name="expensedes" value="<?= e(old('description')) ?>" required></div><div class="module-field"><label>Amount <span class="required">*</span></label><input class="module-input" name="expenseamt" type="number" min="0.01" step="0.01" value="<?= e(old('amount')) ?>" required></div><div class="module-field"><label>Reference</label><input class="module-input" name="reference" maxlength="50" value="<?= e(old('reference')) ?>"></div></div><div class="module-card__footer"><button class="btn btn--primary" type="submit">Add <?= ucfirst($type) ?></button></div></form></div></section></div></div></main>
